1	import type { DeviceType } from "../types/runtime.types.js";
2	export { type DeviceType } from "../types/runtime.types.js";
3	
4	const UA = typeof navigator !== "undefined" ? navigator.userAgent : "";
5	const hasTouch =
6	  typeof navigator !== "undefined" && navigator.maxTouchPoints > 1;
7	
8	function detectDeviceType(): DeviceType {
9	  if (/iPhone|iPod/i.test(UA)) return "ios";
10	  if (/iPad/i.test(UA)) return "ios";
11	  if (/Macintosh/i.test(UA) && hasTouch) return "ios";
12	  if (/Android/i.test(UA)) return "android";
13	  if (/Mobi|Tablet/i.test(UA)) return "android";
14	  return "desktop";
15	}
16	
17	const IS_IOS =
18	  /iPhone|iPod|iPad/i.test(UA) || (/Macintosh/i.test(UA) && hasTouch);
19	
20	function resolveViewportHeight(): number {
21	  if (IS_IOS && typeof window !== "undefined" && window.visualViewport != null) {
22	    return window.visualViewport.height;
23	  }
24	  return window.innerHeight ?? 0;
25	}
26	
27	export class Device {
28	  private _viewportWidth = 0;
29	  private _viewportHeight = 0;
30	  private _deviceType: DeviceType = "unknown";
31	
32	  updateFromWindow(): void {
33	    if (typeof window === "undefined") return;
34	    this._viewportWidth = window.innerWidth ?? 0;
35	    this._viewportHeight = resolveViewportHeight();
36	    this._deviceType = detectDeviceType();
37	  }
38	
39	  get viewportWidth(): number {
40	    return this._viewportWidth;
41	  }
42	
43	  get viewportHeight(): number {
44	    return this._viewportHeight;
45	  }
46	
47	  get deviceType(): DeviceType {
48	    return this._deviceType;
49	  }
50	
51	  get isMobile(): boolean {
52	    return this._deviceType === "ios" || this._deviceType === "android";
53	  }
54	
55	  private static _default: Device | null = null;
56	
57	  static getDefault(): Device {
58	    if (!Device._default) {
59	      Device._default = new Device();
60	      if (typeof window !== "undefined") Device._default.updateFromWindow();
61	    }
62	    return Device._default;
63	  }
64	}
