1	import { Helpers } from "./Helpers.js";
2	import type { ResponsiveNumberRange, ResponsiveNumberValue } from "../types/object.types.js";
3	import { ResponsiveRuntime } from "../runtime/ResponsiveRuntime.js";
4	
5	const DEFAULT_MIN_VIEWPORT = 375;
6	const DEFAULT_MAX_VIEWPORT = 1920;
7	
8	export class ResponsiveValue {
9	  static resolveNumber(
10	    value: ResponsiveNumberValue | undefined,
11	    fallback: number,
12	    viewportWidth = ResponsiveValue.getViewportWidth(),
13	  ): number {
14	    if (typeof value === "number") {
15	      return Number.isFinite(value) ? value : fallback;
16	    }
17	    if (!value) return fallback;
18	
19	    const range = value as ResponsiveNumberRange;
20	    const min = Number.isFinite(range.min) ? range.min : fallback;
21	    const max = Number.isFinite(range.max) ? range.max : min;
22	    const minViewport = ResponsiveValue._resolveViewportBound(
23	      range.minViewport,
24	      DEFAULT_MIN_VIEWPORT,
25	    );
26	    const maxViewport = ResponsiveValue._resolveViewportBound(
27	      range.maxViewport,
28	      DEFAULT_MAX_VIEWPORT,
29	    );
30	    if (maxViewport <= minViewport) return min;
31	
32	    const progress = Helpers.clamp01(
33	      (viewportWidth - minViewport) / (maxViewport - minViewport),
34	    );
35	    return Helpers.lerp(min, max, progress);
36	  }
37	
38	  static getViewportWidth(): number {
39	    return ResponsiveRuntime.getDefault().getSnapshot().viewportWidth;
40	  }
41	
42	  private static _resolveViewportBound(
43	    value: number | undefined,
44	    fallback: number,
45	  ): number {
46	    return typeof value === "number" && Number.isFinite(value) ? value : fallback;
47	  }
48	}
