82	function getNavigatorInfo(): {
83	  hardwareConcurrency: number;
84	  deviceMemory?: number;
85	} {
86	  if (typeof navigator === "undefined") {
87	    return { hardwareConcurrency: 8 };
88	  }
89	  const nav = navigator as Navigator & { deviceMemory?: number };
90	  return {
91	    hardwareConcurrency: nav.hardwareConcurrency ?? 8,
92	    deviceMemory: nav.deviceMemory,
93	  };
94	}
95	
96	function prefersReducedMotion(): boolean {
97	  if (
98	    typeof window === "undefined" ||
99	    typeof window.matchMedia !== "function"
100	  ) {
101	    return false;
102	  }
103	  return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
104	}
105	
106	function getViewportInfo(): {
107	  width: number;
108	  height: number;
109	  dpr: number;
110	  isCompact: boolean;
111	} {
112	  if (typeof window === "undefined") {
113	    return { width: 1440, height: 900, dpr: 1, isCompact: false };
114	  }
115	  const width = window.innerWidth ?? 1440;
116	  const height =
117	    (window.visualViewport != null ? window.visualViewport.height : window.innerHeight) ?? 900;
118	  return {
119	    width,
120	    height,
121	    dpr: window.devicePixelRatio ?? 1,
122	    isCompact: width <= 1024 || height <= 768,
123	  };
124	}
125	
126	function resolveTierFromEnvironment(
127	  environment: ResponsiveEnvironmentInput,
128	): PerformanceTier {
129	  const nav = {
130	    hardwareConcurrency: environment.hardwareConcurrency,
131	    deviceMemory: environment.deviceMemory,
132	  };
133	  const view = {
134	    width: environment.viewportWidth,
135	    height: environment.viewportHeight,
136	    dpr: environment.devicePixelRatio,
137	    isCompact:
138	      environment.viewportWidth <= 1024 || environment.viewportHeight <= 768,
139	  };
140	  const reducedMotion = environment.reducedMotion;
141	
142	  let score = 0;
143	
144	  if (reducedMotion) score += 4;
145	  if (nav.hardwareConcurrency <= 4) score += 2;
146	  else if (nav.hardwareConcurrency <= 6) score += 1;
147	
148	  const memory = nav.deviceMemory;
149	  if (typeof memory === "number" && memory <= 4) score += 2;
150	  else if (typeof memory === "number" && memory <= 8) score += 1;
151	
152	  if (view.isCompact) score += 1;
153	  if (view.dpr >= 2.5) score += 1;
154	
155	  if (score >= 5) return "low";
156	  if (score >= 2) return "mid";
157	  return "high";
158	}
159	
160	function getDefaultEnvironment(): ResponsiveEnvironmentInput {
161	  const nav = getNavigatorInfo();
162	  const view = getViewportInfo();
163	  return {
164	    viewportWidth: view.width,
165	    viewportHeight: view.height,
166	    devicePixelRatio: view.dpr,
167	    isMobile: view.width <= 1024,
168	    reducedMotion: prefersReducedMotion(),
169	    hardwareConcurrency: nav.hardwareConcurrency,
170	    deviceMemory: nav.deviceMemory,
171	  };
172	}
173	
174	export class PerformanceProfile {
175	  static getMainProfile(
176	    environment?: ResponsiveEnvironmentInput,
177	  ): MainPerformanceProfile {
178	    const tier = resolveTierFromEnvironment(
179	      environment ?? getDefaultEnvironment(),
180	    );
181	    const profile =
182	      tier === "low"
183	        ? LOW_PROFILE
184	        : tier === "mid"
185	          ? MID_PROFILE
186	          : HIGH_PROFILE;
187	
188	    return {
189	      ...profile,
190	      bloom: { ...profile.bloom },
191	    };
192	  }
193	}
